cd ~/lab/global/tmp/b7 && cat > t2.mts <<'EOF'
import { readFileSync } from 'fs';
const buf = new Uint8Array(readFileSync('fires_d.mvt'));
let pos = 0;
const varint = () => { let v = 0, shift = 0, b = 0; do { b = buf[pos++]; v += (b & 0x7f) * 2 ** shift; shift += 7; } while (b & 0x80 && shift < 70); return v; };
for (let i = 0; i < 6 && pos < buf.length; i++) { const at = pos; const key = varint(); const len = (key & 7) === 2 ? varint() : -1; console.log('at', at, 'key', key, 'tag', key >> 3, 'wire', key & 7, 'len', len); if (len >= 0) pos += len; }
console.log('total', buf.length);
EOF
node t2.mts

ssh m6 'cd ~/k64-1252; cat > fine2.py <<\EOF"
import subprocess,time,sys
def k():
    for l in subprocess.run(["zprint","kalloc.64"],capture_output=True,text=True).stdout.splitlines():
        f=l.split()
        if f and f[0]=="kalloc.64": return int(f[6])
dur=int(sys.argv[1]); t0=time.time(); pk=k()
while time.time()-t0<dur:
    time.sleep(0.25)
    c=k()
    if c!=pk: print("%.2f %+d"%(time.time(),c-pk),flush=True)
    pk=c
EOF
nohup python3 fine2.py 600 > fine2.log 2>/dev/null & echo $! > fine2.pid; cat fine2.pid'"
